/**
 * ADM tenant administrators: input validation at create (ADM-002, ADM-004).
 *
 * Mail-free: every row is refused by the validator before saving and sending. Empty storage
 * state: each ATC opens its own crypto session and spends one positive Administrator login.
 * trace is off because that login carries live tokens. The tenant is GENERATED by
 * `TenantAdminAccountSteps` in `beforeAll` and always deleted in `afterAll`; if a row is
 * wrongly accepted (an account plus a mail), its id is handed to the Steps and deleted there.
 */

import { TenantAdminAccountSteps } from '@steps/TenantAdminAccountSteps';
import { test } from '@TestFixture';

test.use({ trace: 'off', storageState: { cookies: [], origins: [] } });

test.describe('ADM: tenant administrator input validation', () => {
  const accounts = new TenantAdminAccountSteps();
  let tenantId: number;

  test.beforeAll(async () => {
    test.setTimeout(120000);
    try {
      tenantId = (await accounts.prepareTenant()).id;
    }
    catch (error) {
      await accounts.cleanup().catch(() => undefined);
      throw error;
    }
  });

  test.afterAll(async () => {
    await accounts.cleanup();
  });

  test('ADM-002: should reject an invalid e-mail format or a personal domain', async ({ api }) => {
    test.setTimeout(120000);
    await api.tenantAdmins.rejectInvalidAndPersonalEmails({
      tenantId,
      trackCreated: account => accounts.trackTenantAdmin(account),
    });
  });

  test('ADM-004: should reject a name over 255 and a position over 100 characters', async ({ api }) => {
    await api.tenantAdmins.rejectOversizedNameAndPosition({
      tenantId,
      trackCreated: account => accounts.trackTenantAdmin(account),
    });
  });
});
